mapper.select:
SELECT COALESCE(SUM(i.count), 0)
FROM trade_order_item i
INNER JOIN trade_order o ON o.id = i.order_id AND o.deleted = 0
WHERE i.deleted = 0
  AND i.user_id = #{userId}
  AND i.subscription_student_id = #{studentId}
  AND i.subscription_offer_sku_id = #{offerSkuId}
  AND o.status <> #{canceledStatus}
